import java.util.Scanner;

public class Main {
    public static int computeGCD(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x_input = scanner.nextInt();
        int y_input = scanner.nextInt();
        int limit_input = scanner.nextInt();

        double ratio_target = (double) x_input / y_input;
        double min_diff = 1e9;
        int final_num = 0, final_den = 1;

        for (int i = 1; i <= limit_input; ++i) {
            int b_value = (int) ((long) x_input * i / y_input);
            double[] candidates = {
                (double) b_value / i,
                (double) Math.abs(b_value - 1) / i,
                (double) (b_value + 1) / i
            };
            int[] candidate_nums = {b_value, Math.abs(b_value - 1), b_value + 1};

            for (int j = 0; j < 3; ++j) {
                double diff = Math.abs(ratio_target - candidates[j]);
                if (diff < min_diff) {
                    min_diff = diff;
                    final_num = candidate_nums[j];
                    final_den = i;
                }
            }
        }

        if (Math.abs(1.0 - ratio_target) <= (Math.abs((double) final_num / final_den) - ratio_target) + 1e-9) {
            final_num = 1;
            final_den = 1;
        }

        int gcd_value = computeGCD(final_num, final_den);
        System.out.println((final_num / gcd_value) + "/" + (final_den / gcd_value));
        scanner.close();
    }
}
